/** Browser-only chart contracts, shared by runtime and Designer projections. */
export const WEB_CHART_TYPES: readonly [
    "doughnut",
    "pie",
    "bar",
    "horizontalBar",
    "line",
    "area",
    "radar",
    "polarArea"
];

export type WebChartType = (typeof WEB_CHART_TYPES)[number];

export type WebChartFontFamily = 'inherit' | 'roboto' | 'open-sans' | 'jetbrains-mono' | 'inter' | 'lato' | 'montserrat' | 'poppins' | 'nunito';

export interface WebChartSeriesConfiguration {
    readonly id: string;
    readonly name: string;
    readonly color: string;
    readonly apiClientId: string | null;
    readonly operationId: string | null;
    readonly listPath: string;
    readonly labelField: string;
    readonly valueField: string;
}

export interface WebChartsConfiguration {
    readonly schemaVersion: 1;
    readonly type: WebChartType;
    readonly title: string;
    readonly subtitle: string;
    readonly fontFamily?: WebChartFontFamily;
    readonly legendFontFamily?: WebChartFontFamily;
    readonly textColor?: string | null;
    readonly titleColor?: string | null;
    readonly subtitleColor?: string | null;
    readonly legendColor?: string | null;
    readonly titleIcon?: LucideIconName | null;
    readonly showLegend: boolean;
    readonly legendPosition: 'bottom' | 'right';
    readonly showGrid: boolean;
    readonly showLabels: boolean;
    readonly smooth: boolean;
    readonly stacked: boolean;
    readonly innerRadius: number;
    readonly valuePrefix: string;
    readonly valueSuffix: string;
    readonly decimalPlaces: number;
    readonly emptyText: string;
    readonly series: readonly WebChartSeriesConfiguration[];
}

export interface WebChartPoint {
    readonly label: string;
    readonly value: number;
}

export interface WebChartSeriesData {
    readonly id: string;
    readonly name: string;
    readonly color: string;
    readonly points: readonly WebChartPoint[];
}

/** The original numeric value and category of one activated chart mark. */
export interface WebChartPointEventDetail {
    readonly label: string;
    readonly value: number;
    readonly seriesId: string;
    readonly seriesName: string;
    readonly index: number;
}

export const WEB_CHART_COLORS: readonly [
    "#6366f1",
    "#14b8a6",
    "#f59e0b",
    "#ec4899",
    "#38bdf8"
];

export function webChartColor(value: unknown, index?: number): string;

/** Distinct shades keep a circular series tied to its authored base color. */
export function webChartSliceColor(baseColor: string, index: number): string;

export function normalizeWebChartsConfiguration(value: unknown): WebChartsConfiguration;

/** Invalid pointers and missing properties never select a different value. */
export function webChartPointer(value: unknown, pointer: string): unknown;

export function webChartPoints(rows: readonly unknown[], configuration: WebChartSeriesConfiguration): readonly WebChartPoint[];

export function formatWebChartValue(value: number, configuration: WebChartsConfiguration): string;

export function freezeWebChartData(value: readonly WebChartSeriesData[]): readonly WebChartSeriesData[];

export interface WebChartsRenderOptions {
    readonly interactive?: boolean;
    readonly width?: number;
    readonly height?: number;
    readonly onPointClick?: (detail: WebChartPointEventDetail) => void;
}

/** Shared SVG projection. It creates no subscriptions, observers or API requests. */
export function renderChartsSvg(document: Document, configuration: WebChartsConfiguration, data: readonly WebChartSeriesData[], options?: WebChartsRenderOptions): SVGSVGElement;

export type WebChartPointEventHandler<TSender = WebCharts> = (sender: TSender, event: CustomEvent<WebChartPointEventDetail>) => void | Promise<void>;

/** Responsive, accessible SVG charts whose API bindings observe completed requests. */
export class WebCharts extends WebComponent {
    #private;
    constructor(element: HTMLElement);
    /** Persisted chart appearance and up to five declarative API series. */
    get chartsConfig(): WebChartsConfiguration;
    set chartsConfig(value: WebChartsConfiguration);
    /** Current transient series. Values remain numeric and never enter the Project Model. */
    get data(): readonly WebChartSeriesData[];
    set data(value: readonly WebChartSeriesData[]);
    get selectedLabel(): string | null;
    get selectedValue(): number | null;
    get selectedSeriesId(): string | null;
    set onPointClick(handler: WebChartPointEventHandler<this> | null);
    /** Clears displayed points; an existing binding can refresh after the next successful request. */
    clear(): void;
    /**
     * Binds one configured series to a named API operation by stable operation ID.
     * Reads existing successful data and subsequent results; never executes a request.
     */
    bindApiClient(apiClient: WebApiClient, operationId: string, seriesId: string): () => void;
    dispose(): void;
}
